// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

// 用户模型
model User {
  id            Int       @id @default(autoincrement())
  email         String    @unique
  username      String    @unique
  passwordHash  String
  role          Role      @default(USER)
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  // 关系
  blogs      Blog[]
  comments   Comment[]
  likes      Like[]
  bookmarks  Bookmark[]
  medias     Media[]
}

// 用户角色枚举
enum Role {
  ADMIN
  USER
}

// 分类模型
model Category {
  id          Int       @id @default(autoincrement())
  name        String    @unique
  slug        String    @unique
  description String?
  createdAt   DateTime  @default(now())

  // 关系
  blogs      Blog[]
}

// 标签模型
model Tag {
  id        Int       @id @default(autoincrement())
  name      String    @unique
  slug      String    @unique
  createdAt DateTime  @default(now())

  // 关系
  blogs     Blog[]    @relation("BlogTags")
}

// 博客模型
model Blog {
  id           Int       @id @default(autoincrement())
  title        String
  content      String    @db.Text
  excerpt      String?   @db.Text
  coverImage   String?
  status       BlogStatus @default(DRAFT)
  viewCount    Int       @default(0)
  publishedAt  DateTime?
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt

  // 外键
  authorId     Int
  categoryId   Int?

  // 关系
  author      User      @relation(fields: [authorId], references: [id])
  category    Category? @relation(fields: [categoryId], references: [id])
  tags        Tag[]     @relation("BlogTags")
  comments    Comment[]
  likes       Like[]
  bookmarks   Bookmark[]

  // 索引
  @@index([authorId])
  @@index([categoryId])
  @@index([status])
  @@index([publishedAt])
}

// 博客状态枚举
enum BlogStatus {
  DRAFT
  PUBLISHED
  DELETED
}

// 博客标签关联模型（多对多关系）
model BlogTag {
  blogId    Int
  tagId     Int
  createdAt DateTime @default(now())

  // 关系
  blog      Blog     @relation(fields: [blogId], references: [id])
  tag       Tag      @relation(fields: [tagId], references: [id])

  @@id([blogId, tagId])
  @@index([blogId])
  @@index([tagId])
}

// 评论模型
model Comment {
  id              Int       @id @default(autoincrement())
  content         String    @db.Text
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt

  // 外键
  blogId          Int
  userId          Int
  parentCommentId Int?

  // 关系
  blog            Blog      @relation(fields: [blogId], references: [id])
  user            User      @relation(fields: [userId], references: [id])
  parent          Comment?  @relation("CommentReplies", fields: [parentCommentId], references: [id])
  replies         Comment[] @relation("CommentReplies")

  // 索引
  @@index([blogId])
  @@index([userId])
  @@index([parentCommentId])
}

// 点赞模型
model Like {
  id        Int      @id @default(autoincrement())
  createdAt DateTime @default(now())

  // 外键
  blogId    Int
  userId    Int

  // 关系
  blog      Blog     @relation(fields: [blogId], references: [id])
  user      User     @relation(fields: [userId], references: [id])

  @@unique([blogId, userId])
  @@index([blogId])
  @@index([userId])
}

// 收藏模型
model Bookmark {
  id        Int      @id @default(autoincrement())
  createdAt DateTime @default(now())

  // 外键
  blogId    Int
  userId    Int

  // 关系
  blog      Blog     @relation(fields: [blogId], references: [id])
  user      User     @relation(fields: [userId], references: [id])

  @@unique([blogId, userId])
  @@index([blogId])
  @@index([userId])
}

// 媒体文件模型
model Media {
  id         Int      @id @default(autoincrement())
  filename   String
  filepath   String
  mimeType   String
  size       Int      // bytes
  createdAt  DateTime @default(now())

  // 外键
  uploaderId Int

  // 关系
  uploader   User     @relation(fields: [uploaderId], references: [id])

  @@index([uploaderId])
}

