  await prisma.blogTag.deleteMany();
  await prisma.comment.deleteMany();
  await prisma.like.deleteMany();
  await prisma.bookmark.deleteMany();
  await prisma.media.deleteMany();
  await prisma.blog.deleteMany();
  await prisma.category.deleteMany();
  await prisma.tag.deleteMany();
  await prisma.user.deleteMany();

  console.log('Cleared existing data.');

  // 1. 创建用户
  const adminPassword = await bcrypt.hash('admin123', 10);
  const userPassword = await bcrypt.hash('user123', 10);

  const admin = await prisma.user.create({
    data: {
      email: 'admin@example.com',
      username: 'admin',
      passwordHash: adminPassword,
      role: Role.ADMIN,
    },
  });
  const user = await prisma.user.create({
    data: {
      email: 'user@example.com',
      username: 'john_doe',
      passwordHash: userPassword,
      role: Role.USER,
    },
  });

  console.log('Created users:', admin.email, user.email);

  // 2. 创建分类
  const categories = await Promise.all([
    prisma.category.create({
      data: {
        name: '技术',
        slug: 'technology',
        description: '关于编程、开发、技术的文章',
      },
    }),
    prisma.category.create({
      data: {
        name: '生活',
        slug: 'life',
        description: '日常生活、感悟、随笔',
      },
    }),
    prisma.category.create({
      data: {
        name: '旅行',
        slug: 'travel',
        description: '旅行游记、景点推荐',
      },
    }),
    prisma.category.create({
      data: {
        name: '美食',
        slug: 'food',
        description: '美食分享、食谱、餐厅评测',
      },
    }),
    prisma.category.create({
      data: {
        name: '随笔',
        slug: 'essay',
        description: '随意写作，杂谈',
      },
    }),
  ]);

  console.log('Created categories:', categories.map(c => c.name).join(', '));

  // 3. 创建标签
  const tagNames = [
    'JavaScript', 'React', 'Node.js', 'TypeScript', 'Python',
    '前端开发', '后端开发', '数据库', '算法', '设计模式',
    '旅行日记', '美食分享', '生活感悟', '读书笔记', '电影推荐'
  ];
  const tags = await Promise.all(
    tagNames.map(name =>
      prisma.tag.create({
        data: {
          name,
          slug: name.toLowerCase().replace(/\s+/g, '-'),
        },
      })
    )
  );

  console.log('Created tags:', tags.map(t => t.name).join(', '));

  // 4. 创建博客
  const blogs = [];
  const blogTitles = [
    'React Hooks 入门指南',
    'Node.js 异步编程最佳实践',
    'TypeScript 高级类型技巧',
    '我的日本旅行日记',
    '如何制作美味的意大利面',
    '前端性能优化实战',
    '数据库索引原理与优化',
    '生活中的小确幸',
    '读书分享：《黑客与画家》',
    '电影推荐：《星际穿越》',
    'Python 数据分析入门',
    'React 状态管理对比',
    'Node.js 微服务架构',
    '旅行中的摄影技巧',
    '健康饮食的重要性'
  ];

  const loremContent = `Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.

  Sed ut perspiciatis unde omnis iste natus error sit voluptatem accusantium doloremque laudantium, totam rem aperiam, eaque ipsa quae ab illo inventore veritatis et quasi architecto beatae vitae dicta sunt explicabo. Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit, sed quia consequuntur magni dolores eos qui ratione voluptatem sequi nesciunt.

  Neque porro quisquam est, qui dolorem ipsum quia dolor sit amet, consectetur, adipisci velit, sed quia non numquam eius modi tempora incidunt ut labore et dolore magnam aliquam quaerat voluptatem.`;

  for (let i = 0; i < blogTitles.length; i++) {
    const title = blogTitles[i];
    const status = i % 3 === 0 ? BlogStatus.DRAFT : BlogStatus.PUBLISHED; // 部分草稿
    const publishedAt = status === BlogStatus.PUBLISHED ? new Date(Date.now() - i * 86400000) : null;
    const author = i % 2 === 0 ? admin : user; // 交替作者
    const category = categories[i % categories.length];

    const blog = await prisma.blog.create({
      data: {
        title,
        content: loremContent,
        excerpt: `这是关于 "${title}" 的摘要，简要介绍文章内容。`,
        coverImage: i % 4 === 0 ? `https://picsum.photos/800/400?random=${i}` : null,
        status,
        viewCount: Math.floor(Math.random() * 1000),
        publishedAt,
        authorId: author.id,
        categoryId: category.id,
      },
    });
    blogs.push(blog);

    // 为每篇博客关联随机标签
    const selectedTags = tags.sort(() => 0.5 - Math.random()).slice(0, Math.floor(Math.random() * 4) + 2); // 2-5个标签
    for (const tag of selectedTags) {
      await prisma.blogTag.create({
        data: {
          blogId: blog.id,
          tagId: tag.id,
        },
      });
    }

    // 如果博客已发布，创建评论
    if (status === BlogStatus.PUBLISHED) {
      const commentCount = Math.floor(Math.random() * 4) + 2; // 2-5条评论
      for (let j = 0; j < commentCount; j++) {
        const commentAuthor = j % 2 === 0 ? admin : user;
        await prisma.comment.create({
          data: {
            content: `这是用户 ${commentAuthor.username} 对博客 "${title}" 的第 ${j + 1} 条评论。非常精彩的文章！`,
            blogId: blog.id,
            userId: commentAuthor.id,
          },
        });
      }

      // 创建点赞和收藏（模拟部分用户行为）
      if (i % 2 === 0) {
        await prisma.like.create({
          data: {
            blogId: blog.id,
            userId: admin.id,
          },
        });
      }
      if (i % 3 === 0) {
        await prisma.bookmark.create({
          data: {
            blogId: blog.id,
            userId: user.id,
          },
        });
      }
    }
  }

  console.log(`Created ${blogs.length} blogs with tags, comments, likes, bookmarks.`);

  // 5. 创建媒体文件（示例）
  const media = await prisma.media.create({
    data: {
      filename: 'example.jpg',
      filepath: '/uploads/example.jpg',
      mimeType: 'image/jpeg',
      size: 1024 * 1024,
      uploaderId: admin.id,
    },
  });
  console.log('Created media file:', media.filename);

  console.log('Seeding finished.');
}

main()
  .catch((e) => {
    console.error('Seeding error:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

