-- Enable FTS5 if not already enabled (not needed in modern SQLite)
-- Create virtual table for full-text search
CREATE VIRTUAL TABLE IF NOT EXISTS BlogFTS USING fts5(
    title,
    content,
    excerpt,
    blogId UNINDEXED  -- store reference to original blog, not indexed
);

-- Insert existing blog data into FTS table
INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
SELECT rowid, title, content, excerpt, id FROM Blog WHERE status = 'PUBLISHED';

-- Trigger for INSERT
CREATE TRIGGER IF NOT EXISTS blog_ai AFTER INSERT ON Blog
BEGIN
    INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
    VALUES (new.rowid, new.title, new.content, new.excerpt, new.id);
END;

-- Trigger for UPDATE
CREATE TRIGGER IF NOT EXISTS blog_au AFTER UPDATE ON Blog
BEGIN
    DELETE FROM BlogFTS WHERE rowid = old.rowid;
    INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
    VALUES (new.rowid, new.title, new.content, new.excerpt, new.id);
END;

-- Trigger for DELETE
CREATE TRIGGER IF NOT EXISTS blog_ad AFTER DELETE ON Blog
BEGIN
    DELETE FROM BlogFTS WHERE rowid = old.rowid;
END;

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function main() {
  try {
    // Test FTS5 table exists
    const result = await prisma.$queryRaw`SELECT COUNT(*) as count FROM BlogFTS`;
    console.log('BlogFTS row count:', result);

    // Test a simple search
    const searchResult = await prisma.$queryRaw`
      SELECT blogId, title, snippet(BlogFTS, 2, '<b>', '</b>', '...', 20) as snippet
      FROM BlogFTS
      WHERE BlogFTS MATCH 'React'
      ORDER BY rank
      LIMIT 3
    `;
    console.log('Search results for "React":', JSON.stringify(searchResult, null, 2));

    // Check if FTS5 is available
    const fts5Check = await prisma.$queryRaw`SELECT * FROM pragma_compile_options WHERE compile_options LIKE '%FTS5%'`;
    console.log('FTS5 compile options:', fts5Check);
  } catch (error) {
    console.error('Error:', error);
  } finally {
    await prisma.$disconnect();
  }
}

main();

