import prisma, { fullTextSearch, getBlogWithDetails, getPopularBlogs } from '../src/db';

async function testFullTextSearch() {
  console.log('Testing full-text search...');
  const result = await fullTextSearch({ query: 'React', pageSize: 5 });
  console.log('Search results for "React":');
  console.log(`Total matches: ${result.total}`);
  console.log(`Page: ${result.page}/${result.totalPages}`);
  result.items.forEach((item, idx) => {
    console.log(`[${idx + 1}] ${item.title} (rank: ${item.rank})`);
    console.log(`   Snippet: ${item.snippet}`);
  });
}

async function testGetBlogWithDetails() {
  console.log('\nTesting getBlogWithDetails...');
  const blog = await prisma.blog.findFirst({
    where: { status: 'PUBLISHED' },
    select: { id: true },
  });
  if (!blog) {
    console.log('No published blog found');
    return;
  }
  const details = await getBlogWithDetails(blog.id);
  if (!details) {
    console.log('Blog not found');
    return;
  }
  console.log(`Blog: ${details.title}`);
  console.log(`Author: ${details.author.username}`);
  console.log(`Category: ${details.category?.name ?? 'None'}`);
  console.log(`Tags: ${details.tags.map(t => t.tag.name).join(', ')}`);
  console.log(`Comments: ${details._count.comments}`);
  console.log(`Likes: ${details._count.likes}`);
  console.log(`Bookmarks: ${details._count.bookmarks}`);
}

async function testGetPopularBlogs() {
  console.log('\nTesting getPopularBlogs...');
  const blogs = await getPopularBlogs(3);
  console.log('Popular blogs:');
  blogs.forEach((blog, idx) => {
    console.log(`[${idx + 1}] ${blog.title} (views: ${blog.viewCount}, likes: ${blog._count.likes}, comments: ${blog._count.comments})`);
  });
}

async function main() {
  try {
    await testFullTextSearch();
    await testGetBlogWithDetails();
    await testGetPopularBlogs();
  } catch (error) {
    console.error('Test error:', error);
  } finally {
    await prisma.$disconnect();
  }
}

main();

