import prisma from './src/db';

async function main() {
  // Check total rows in BlogFTS
  const total = await prisma.$queryRaw`SELECT COUNT(*) as count FROM BlogFTS`;
  console.log('Total rows in BlogFTS:', total);

  // Check some sample rows
  const samples = await prisma.$queryRaw`SELECT blogId, title FROM BlogFTS LIMIT 5`;
  console.log('Sample rows:', samples);

  // Check if any row contains 'React' in title column
  const reactMatch = await prisma.$queryRaw`SELECT blogId, title FROM BlogFTS WHERE title LIKE '%React%' LIMIT 5`;
  console.log('Rows with React in title:', reactMatch);

  // Try MATCH with simple term
  const matchResult = await prisma.$queryRaw`SELECT blogId, rank FROM BlogFTS WHERE BlogFTS MATCH 'React' LIMIT 5`;
  console.log('MATCH React result:', matchResult);

  // Check FTS5 configuration
  const config = await prisma.$queryRaw`SELECT * FROM pragma_compile_options WHERE compile_options LIKE '%FTS%'`;
  console.log('FTS compile options:', config);

