-- Drop existing triggers
DROP TRIGGER IF EXISTS blog_ai;
DROP TRIGGER IF EXISTS blog_au;
DROP TRIGGER IF EXISTS blog_ad;

-- Drop existing virtual table
DROP TABLE IF EXISTS BlogFTS;

-- Create virtual table for full-text search
CREATE VIRTUAL TABLE BlogFTS USING fts5(
    title,
    content,
    excerpt,
    blogId UNINDEXED  -- store reference to original blog, not indexed
);

-- Insert all blog data into FTS table (including drafts)
INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
SELECT rowid, title, content, excerpt, id FROM Blog;

-- Trigger for INSERT
CREATE TRIGGER blog_ai AFTER INSERT ON Blog
BEGIN
    INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
    VALUES (new.rowid, new.title, new.content, new.excerpt, new.id);
END;

-- Trigger for UPDATE
CREATE TRIGGER blog_au AFTER UPDATE ON Blog
BEGIN
    DELETE FROM BlogFTS WHERE rowid = old.rowid;
    INSERT INTO BlogFTS (rowid, title, content, excerpt, blogId)
    VALUES (new.rowid, new.title, new.content, new.excerpt, new.id);
END;

-- Trigger for DELETE
CREATE TRIGGER blog_ad AFTER DELETE ON Blog
BEGIN
    DELETE FROM BlogFTS WHERE rowid = old.rowid;
END;

