import { PrismaClient, BlogStatus } from '@prisma/client';

const prisma = new PrismaClient();

export default prisma;

/**
 * 分页参数
 */
export interface PaginationParams {
  page?: number;
  pageSize?: number;
}

/**
 * 分页结果
 */
export interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
}

/**
 * 构建分页查询选项
 */
export function buildPaginationOptions(params: PaginationParams) {
  const page = params.page && params.page > 0 ? params.page : 1;
  const pageSize = params.pageSize && params.pageSize > 0 ? params.pageSize : 10;
  const skip = (page - 1) * pageSize;
  const take = pageSize;
  return { skip, take, page, pageSize };
}

/**
 * 创建分页响应
 */
export function createPaginatedResponse<T>(
  items: T[],
  total: number,
  page: number,
  pageSize: number
): PaginatedResult<T> {
  const totalPages = Math.ceil(total / pageSize);
  return {
    items,
    total,
    page,
    pageSize,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  };
}

/**
 * 全文搜索参数
 */
export interface FullTextSearchParams {
  query: string;
  page?: number;
  pageSize?: number;
  includeDrafts?: boolean; // 是否包含草稿
}

/**
 * 全文搜索结果项
 */
export interface SearchResultItem {
  id: number;
  title: string;
  excerpt: string | null;
  content: string;
  snippet: string;
  rank: number;
}

/**
 * 执行全文搜索
 */
export async function fullTextSearch(
  params: FullTextSearchParams
): Promise<PaginatedResult<SearchResultItem>> {
  const { query, page = 1, pageSize = 10, includeDrafts = false } = params;
  const { skip, take } = buildPaginationOptions({ page, pageSize });

  // 构建MATCH表达式
  const searchQuery = query.trim();
  if (!searchQuery) {
    return createPaginatedResponse([], 0, page, pageSize);
  }

  // 首先获取匹配的博客ID和排名
  const matched = (await prisma.$queryRaw`
    SELECT blogId, rank
    FROM BlogFTS
    WHERE BlogFTS MATCH ${searchQuery}
    ORDER BY rank
    LIMIT ${take} OFFSET ${skip}
  `) as Array<{ blogId: bigint; rank: number }>;

  // 获取总匹配数
  const totalResult = (await prisma.$queryRaw`
    SELECT COUNT(*) as total
    FROM BlogFTS
    WHERE BlogFTS MATCH ${searchQuery}
  `) as Array<{ total: bigint }>;
  const total = Number(totalResult[0].total);

  if (matched.length === 0) {
    return createPaginatedResponse([], total, page, pageSize);
  }

  // 获取博客详情和片段
  const blogIds = matched.map((m) => Number(m.blogId)); // convert BigInt to number
  const rankMap = new Map(matched.map((m) => [Number(m.blogId), m.rank]));

  const blogs = await prisma.blog.findMany({
    where: {
      id: { in: blogIds },
      status: includeDrafts ? undefined : BlogStatus.PUBLISHED,
    },
    select: {
      id: true,
      title: true,
      excerpt: true,
      content: true,
    },
  });

  // 为每个博客获取搜索片段
  const snippets = (await prisma.$queryRaw`
    SELECT blogId, snippet(BlogFTS, 2, '<b>', '</b>', '...', 80) as snippet
    FROM BlogFTS
    WHERE blogId IN (${blogIds.join(',')}) AND BlogFTS MATCH ${searchQuery}
  `) as Array<{ blogId: bigint; snippet: string }>;

  const snippetMap = new Map(snippets.map((s) => [Number(s.blogId), s.snippet]));

  // 构建结果项
  const items: SearchResultItem[] = blogs.map((blog) => ({
    id: blog.id,
    title: blog.title,
    excerpt: blog.excerpt,
    content: blog.content,
    snippet: snippetMap.get(blog.id) || '',
    rank: rankMap.get(blog.id) || 0,
  }));

  // 按原始排名排序
  items.sort((a, b) => a.rank - b.rank);

  return createPaginatedResponse(items, total, page, pageSize);
}

